// Hearth Keys -- measured data of the grand piano recordings.
//
// The grand is built on the Salamander Grand Piano V3 (a Yamaha C5 recorded
// by Alexander Holm, CC BY 3.0): 30 notes in minor thirds, 16 strike
// strengths each, plus key-release noises, release tails and pedal noises.
// The audio itself lives in the sample pack; this table holds what the
// engine needs to know about every recording: length, scale, loudness,
// brightness, decay, tuning and string stiffness.  It is generated by
// tools/grand/make_table.py.
#pragma once

#include <cstdint>

namespace hk {

constexpr int kGrandRoots = 30;        // sampled notes: A0, C1, D#1 ... C8
constexpr int kGrandLayers = 16;       // strike strengths per sampled note
constexpr int kGrandTailRoots = 23;    // release tails: A0 ... D#6
constexpr int kGrandEnvPoints = 10;
constexpr int kGrandPartials = 20;     // partial frequencies kept per sampled note
constexpr int kGrandFiles = 641;
constexpr int kGrandPackVersion = 1;
constexpr double kGrandRate = 48000.0;
constexpr int kGrandLastDamper = 88;   // highest key with a damper (E6)

struct GrandFile {
    const char* name;     // file name in the pack, without extension
    uint32_t frames;      // stereo frames
    float scale;          // 16-bit sample value -> original amplitude
    uint64_t sum;         // checksum of the samples
};

struct GrandLayer {
    uint16_t file;
    float level;                    // natural loudness of the attack, dB (K-weighted, 200 ms)
    float bright;                   // share of energy above the note's shelf corner, dB
    float env[kGrandEnvPoints];     // level over time, dB re the attack
};

struct GrandNote {
    uint8_t root;         // MIDI note
    float cents;          // tuning of the first partial against equal temperament
    float f1;             // first partial, Hz, at A = 440
    float B;              // string stiffness (inharmonicity coefficient), the trend of the partials
    float top;            // loudness of the hardest strike, smoothed over the keyboard, dB
    float shelfHz;        // corner of the brightness measure
    float partial[kGrandPartials];    // the partials as measured, Hz, at A = 440
    GrandLayer layer[kGrandLayers];   // ordered from the softest to the hardest strike
};

struct GrandTail {
    uint16_t file;
    float level;          // natural loudness over its first second, dB
};

extern const float kGrandEnvTime[kGrandEnvPoints];
extern const GrandFile kGrandFile[kGrandFiles];
extern const GrandNote kGrandNote[kGrandRoots];
extern const GrandTail kGrandTail[3][kGrandTailRoots];   // loud, soft, softest
extern const uint16_t kGrandRel[88];
extern const float kGrandRelLevel[88];
extern const uint16_t kGrandPedal[4];                    // down 1, down 2, up 1, up 2

}  // namespace hk
